sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	var testdata = new x_snc_devtools.TestDataAPI('ATF.CODESANITY');

	test.SetResult(true);

	var strCheck = '1ba85eeb509340528e880bb6e71ac2b9';

	// Not client callable
	var strRecordSysId = testdata.CreateScriptInclude(
		'global',
		'Test_Good1',
		'function Test_Good1()\n'
		+'{ return true; }');
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strRecordSysId,false);

	// Client callable, derived from AbstractAjaxProcessor and using "this"
	var strRecordSysId = testdata.CreateScriptInclude(
		'global',
		'Test_Good2',
		"var Test_Good2 = Class.create();\n"
		+ "Test_Good2.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {\n"
		+ "    getTest: function() {\n"
		+ "        var value = GetParam('test', '', this);\n"
		+ "        return value;\n"
		+ "    },\n"
		+ "    type: 'Test_Good2'\n"
		+ "});\n",
		'public',
		'',
		true);
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strRecordSysId,false);	

	// Client callable, NOT derived from AbstractAjaxProcessor, NOT using "this"
	var strRecordSysId = testdata.CreateScriptInclude(
		'global',
		'Test_Good3',
		"var Test_Good3 = Class.create();\n"
		+ "Test_Good3.prototype = {\n"
		+ "    process: function() {\n"
		+ "        var value = GetParam('test', '');\n"
		+ "        return value;\n"
		+ "    },\n"
		+ "    type: 'Test_Good3'\n"
		+ "};\n",
		'public',
		'',
		true);
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strRecordSysId,false);		

	// NOT Client callable, derived from AbstractAjaxProcessor, NOT using "this"
	var strRecordSysId = testdata.CreateScriptInclude(
		'global',
		'Test_Good4',
		"var Test_Good4 = Class.create();\n"
		+ "Test_Good4.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {\n"
		+ "    getTest: function() {\n"
		+ "        var value = GetParam('test', '');\n"
		+ "        return value;\n"
		+ "    },\n"
		+ "    type: 'Test_Good4'\n"
		+ "});\n",
		'public',
		'',
		false);
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strRecordSysId,false);			



	// Client callable, derived from AbstractAjaxProcessor, NOT using "this"
	var strRecordSysId = testdata.CreateScriptInclude(
		'global',
		'Test_Bad1',
		"var Test_Bad1 = Class.create();\n"
		+ "Test_Bad1.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {\n"
		+ "    getTest: function() {\n"
		+ "        var value = GetParam('test', '');\n"
		+ "        return value;\n"
		+ "    },\n"
		+ "    type: 'Test_Bad1'\n"
		+ "});\n",
		'public',
		'',
		true);
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strRecordSysId,true);	

	

	return test.GetResult();
})(outputs, steps, stepResult, assertEqual);
